krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code retval = KRB5KDC_ERR_NOPOLICY;
    krb5_db_entry *server = NULL;

    *server_ptr = NULL;
    *status = NULL;

    /* Assert that the principal is a cross TGS principal */
    if (!krb5_is_krbtgt(princ)) {
        *status = "Principal is not a TGS principal.";
        return KRB5KDC_ERR_BADOPTION;
    }

    /* Traverse the realm tree to find possible TGS servers */
    while (kdc_active_realm) {
        krb5_db_entry *tgs_server = NULL;
        krb5_error_code code = find_tgs_server_in_realm(kdc_active_realm, &tgs_server);

        if (code != 0) {
            kdc_active_realm = kdc_active_realm->next;
            continue;
        }

        /* Ignore the first entry (likely the current TGS) */
        if (server == NULL) {
            server = tgs_server;
            kdc_active_realm = kdc_active_realm->next;
            continue;
        }

        /* Check if the current TGS server is available */
        if (is_server_available(tgs_server)) {
            *server_ptr = tgs_server;
            *status = "Alternate TGS found.";
            return 0;
        }

        kdc_active_realm = kdc_active_realm->next;
    }

    /* No suitable TGS found */
    *status = "No alternate TGS found.";
    krb5_db_free_princ(server);

    return retval;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code ret = KRB5_KDC_INVALID_SVC;
    krb5_db_entry *tgs_entry = NULL;
    krb5_principal tgs_princ = NULL;
    krb5_principal target_princ = NULL;
    kdc_realm_t *realm = NULL;

    /* Verify that the principal is a cross TGS principal */
    if (!krb5_is_kdc_principal(princ)) {
        *status = "Principal is not a valid TGS principal.";
        return KRB5_KDC_ERR_BADOPTION;
    }

    /* Traverse the realm tree to find alternate TGS servers */
    for (realm = kdc_active_realm->child_realms; realm; realm = realm->next) {
        /* Skip the first entry as per logic */
        if (realm == kdc_active_realm->child_realms->next) {
            continue;
        }

        ret = krb5_build_principal_realm(krb5_context, &tgs_princ, realm->realm, 0, NULL);
        if (ret != 0) {
            *status = "Failed to build alternate TGS principal.";
            return ret;
        }

        ret = krb5_db_get_principal(krb5_context, tgs_princ, &tgs_entry, 0);
        if (ret != 0) {
            krb5_free_principal(krb5_context, tgs_princ);
            continue;
        }

        if (tgs_entry != NULL && krb5_db_entry_is_tgs(tgs_entry)) {
            *server_ptr = tgs_entry;
            *status = "Alternate TGS found.";
            return 0;
        }

        krb5_db_free_principal(krb5_context, tgs_entry);
        krb5_free_principal(krb5_context, tgs_princ);
    }

    /* No alternate TGS found */
    *server_ptr = NULL;
    *status = "No suitable alternate TGS found.";
    return KRB5_KDC_ERR_SVRUNREACH;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code ret = KRB5_KDC_ERR_NONE;
    krb5_db_entry *server = NULL;
    krb5_principal tgs_princ = NULL;
    kdc_realm_t *r;

    *server_ptr = NULL;
    *status = NULL;

    if (!princ || !kdc_active_realm) {
        return KRB5_ERR_BADOPTION;
    }

    // Check that the principal is a cross TGS principal
    if (!krb5_is_krbtgt_principal(princ)) {
        return KRB5_ERR_BADOPTION;
    }

    // Walk the realm tree to find alternate TGS servers
    for (r = kdc_active_realm; r != NULL; r = r->next) {
        if (r->tgs_entry == NULL) {
            continue;
        }

        // Skip the first entry in the list
        if (r == kdc_active_realm) {
            continue;
        }

        server = r->tgs_entry;
        // Check if this TGS is suitable for use
        if (server && server->princ) {
            *server_ptr = server;
            *status = "Alternate TGS found in realm.";
            return KRB5_KDC_ERR_NONE;
        }
    }

    // No suitable TGS found
    *status = "No alternate TGS found.";
    *server_ptr = NULL;
    return KRB5_ERR_NO_TGS_FOR_SERVER;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code retval = KRB5_KDC_INVALID_REQUEST;
    krb5_db_entry *server = NULL;
    kdc_realm_t *kr;
    int found = 0;

    *server_ptr = NULL;
    *status = NULL;

    if (!princ || krb5_princ_is_not_crossrealm(princ)) {
        *status = "Provided principal is not a valid cross-realm TGS principal.";
        return retval;
    }

    for (kr = kdc_active_realm->next_realm; kr; kr = kr->next_realm) {
        if (kr->tgs_principal && krb5_princ_equal(kr->tgs_principal, princ)) {
            server = kr->tgs_server_entry;
            if (server && server->princ && krb5_db_entry_is_valid(server)) {
                *server_ptr = server;
                *status = "Alternate TGS found successfully.";
                return 0;
            }
        }
    }

    if (!found) {
        *status = "No suitable alternate TGS found.";
        retval = KRB5_KDC_NO_TGS_AVAILABLE;
    }

    return retval;
}

krb5_error_code find_alternate_tgs(kdc_realm_t *kdc_active_realm, krb5_principal princ, krb5_db_entry **server_ptr, const char **status) {
    krb5_error_code ret = KRB5_KDC_NO_TGS;
    krb5_db_entry *tgs_entry = NULL;
    int found = 0;

    /* Assert that the principal is a cross TGS principal */
    if (!krb5_is_krbtgt_principal(princ)) {
        *status = "Provided principal is not a valid cross TGS principal.";
        return KRB5_BAD_PRINCIPAL;
    }

    /* Walk the realm tree to find potential TGS servers */
    kdc_realm_t *realm = kdc_active_realm;
    while (realm) {
        int i;
        for (i = 1; i < realm->tgs_servers->len; ++i) { /* Skip first entry */
            tgs_entry = g_ptr_array_index(realm->tgs_servers, i);
            if (tgs_entry && tgs_entry->valid && tgs_entry->available) {
                *server_ptr = tgs_entry;
                *status = "Alternate TGS found.";
                found = 1;
                break;
            }
        }
        if (found) {
            break;
        }
        realm = realm->parent;
    }

    if (!found) {
        *server_ptr = NULL;
        *status = "No alternate TGS found in the realm tree.";
        ret = KRB5_KDC_NO_TGS;
    }

    return ret;
}
